import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';

const STATES = new Set(['pending', 'succeeded', 'failed']);

function compareIds(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

class MinHeap {
  #items = [];

  get size() {
    return this.#items.length;
  }

  push(value) {
    let index = this.#items.length;
    this.#items.push(value);
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (compareIds(this.#items[parent], value) <= 0) break;
      this.#items[index] = this.#items[parent];
      index = parent;
    }
    this.#items[index] = value;
  }

  pop() {
    const smallest = this.#items[0];
    const last = this.#items.pop();
    if (this.#items.length === 0) return smallest;

    let index = 0;
    while (true) {
      const left = index * 2 + 1;
      if (left >= this.#items.length) break;
      const right = left + 1;
      let child = left;
      if (right < this.#items.length &&
          compareIds(this.#items[right], this.#items[left]) < 0) {
        child = right;
      }
      if (compareIds(this.#items[child], last) >= 0) break;
      this.#items[index] = this.#items[child];
      index = child;
    }
    this.#items[index] = last;
    return smallest;
  }
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Job specification must be an array');

  const jobs = new Map();
  for (const entry of spec) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new Error('Each job must be an object');
    }
    if (typeof entry.id !== 'string' || entry.id.length === 0) {
      throw new Error('Each job id must be a nonempty string');
    }
    if (!Array.isArray(entry.deps)) {
      throw new Error(`Dependencies for ${entry.id} must be an array`);
    }
    if (!STATES.has(entry.state)) throw new Error(`Invalid state for ${entry.id}`);
    if (jobs.has(entry.id)) throw new Error(`Duplicate job id: ${entry.id}`);

    const dependencyIds = new Set();
    for (const dependency of entry.deps) {
      if (typeof dependency !== 'string' || dependency.length === 0) {
        throw new Error(`Dependencies for ${entry.id} must be nonempty strings`);
      }
      if (dependencyIds.has(dependency)) {
        throw new Error(`Duplicate dependency ${dependency} for ${entry.id}`);
      }
      dependencyIds.add(dependency);
    }

    // Retain only validated values in fresh containers; never alter the input.
    jobs.set(entry.id, { id: entry.id, deps: [...entry.deps], state: entry.state });
  }

  const indegree = new Map();
  const children = new Map();
  for (const id of jobs.keys()) {
    indegree.set(id, 0);
    children.set(id, []);
  }
  for (const job of jobs.values()) {
    indegree.set(job.id, job.deps.length);
    for (const dependency of job.deps) {
      if (!jobs.has(dependency)) {
        throw new Error(`Unknown dependency ${dependency} for ${job.id}`);
      }
      children.get(dependency).push(job.id);
    }
  }

  const available = new MinHeap();
  for (const [id, degree] of indegree) {
    if (degree === 0) available.push(id);
  }

  const topological = [];
  while (available.size > 0) {
    const id = available.pop();
    topological.push(id);
    for (const child of children.get(id)) {
      const degree = indegree.get(child) - 1;
      indegree.set(child, degree);
      if (degree === 0) available.push(child);
    }
  }
  if (topological.length !== jobs.size) throw new Error('Dependency cycle detected');

  const failedAncestors = new Map();
  for (const id of jobs.keys()) failedAncestors.set(id, new Set());
  for (const id of topological) {
    const job = jobs.get(id);
    const inherited = failedAncestors.get(id);
    if (job.state === 'failed') inherited.add(id);
    for (const child of children.get(id)) {
      const childCauses = failedAncestors.get(child);
      for (const cause of inherited) childCauses.add(cause);
    }
  }

  const order = topological.filter(id => {
    const job = jobs.get(id);
    return job.state === 'pending' && failedAncestors.get(id).size === 0;
  });

  const pendingById = [...jobs.values()]
    .filter(job => job.state === 'pending')
    .sort((left, right) => compareIds(left.id, right.id));

  const ready = pendingById
    .filter(job => failedAncestors.get(job.id).size === 0 &&
      job.deps.every(dependency => jobs.get(dependency).state === 'succeeded'))
    .map(job => job.id);

  const blocked = pendingById
    .filter(job => failedAncestors.get(job.id).size > 0)
    .map(job => ({
      id: job.id,
      causes: [...failedAncestors.get(job.id)].sort(compareIds),
    }));

  return { order, ready, blocked };
}

function runCli() {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    process.stdout.write(`${JSON.stringify(planJobs(spec))}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message || 'Unable to create job plan'}\n`);
    process.exitCode = 2;
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  runCli();
}

